// Ley de Amdahl: aceleración = 1 / ((1 - p) + p / N)
const aceleracion = (p, n) => 1 / ((1 - p) + p / n);
const nucleos = [2, 4, 8, 16, 64, 1000];

for (const p of [0.5, 0.8, 0.95]) {
  const filas = nucleos.map(n => `${n} núcleos: ${aceleracion(p, n).toFixed(2)}x`);
  console.log(`p = ${p} (serial ${(1 - p) * 100}%) -> techo ${(1 / (1 - p)).toFixed(0)}x`);
  console.log('   ' + filas.join(' | '));
}
